reply:
{
  "title": "Protected Zones for Endangered Civilians",
  "setting": "Bosnia-Herzegovina, 30 October 1992; an ICRC appeal to the international community and the UN Security Council.",
  "decider": "The international community",
  "agent_recast": false,
  "recast_note": "",
  "agent": "The international community",
  "agent_role": "decide",
  "situation": "Civilians belonging to ethnic minorities or defeated sides in Bosnia-Herzegovina face intimidation, violence, internment, deportation, and other dangers, with conditions deteriorating in northern and central areas. At least 100,000 Muslims in northern Bosnia-Herzegovina are described as terrorized and wishing to reach safety. No third country appears ready to grant asylum to refugees on that scale, even provisionally. Winter is approaching and may arrive before a peace agreement is signed and implemented; unprotected transfers have exposed civilians to deadly crossfire and sniper attacks. Any protected zone would need suitable hygiene and protection, clearly established international responsibility, agreement by the parties concerned, and sufficient international support.",
  "question": "What should the international community do about establishing a protected zone in northern Bosnia-Herzegovina?",
  "facts": [
    {
      "id": "F1",
      "kind": "situation",
      "status": "assessed",
      "fact": "Civilians belonging to ethnic minorities or defeated sides face intimidation, threats, harassment, brutality, expropriation, torture, hostage taking, internment, deportation, and summary executions, and conditions are deteriorating in northern and central Bosnia-Herzegovina.",
      "spans": [
        "src:50142ad6d920#p1.2"
      ]
    },
    {
      "id": "F2",
      "kind": "situation",
      "status": "assessed",
      "fact": "At least 100,000 Muslims live in northern Bosnia-Herzegovina, are terrorized, and wish to be transferred to a safe haven.",
      "spans": [
        "src:50142ad6d920#p1.2"
      ]
    },
    {
      "id": "F3",
      "kind": "situation",
      "status": "assessed",
      "fact": "No third country appears ready, even provisionally, to grant asylum to 100,000 Bosnian refugees.",
      "spans": [
        "src:50142ad6d920#p1.3"
      ]
    },
    {
      "id": "F4",
      "kind": "situation",
      "status": "assessed",
      "fact": "Winter is approaching and is likely to reach Bosnia-Herzegovina before a peace agreement is signed and implemented.",
      "spans": [
        "src:50142ad6d920#p1.5"
      ]
    },
    {
      "id": "F5",
      "kind": "situation",
      "status": "assessed",
      "fact": "Forced, unprotected transfers have exposed civilians crossing frontlines on foot to crossfire and deliberate sniper attacks, and there is no cease-fire.",
      "spans": [
        "src:50142ad6d920#p1.5"
      ]
    },
    {
      "id": "F6",
      "kind": "authority",
      "status": "confirmed",
      "fact": "International humanitarian law includes various kinds of safety zones, while the circumstances call for zones adapted to the specific requirements and requiring international protection.",
      "spans": [
        "src:50142ad6d920#p1.3"
      ]
    },
    {
      "id": "F7",
      "kind": "authority",
      "status": "confirmed",
      "fact": "Protected zones must meet appropriate hygiene standards, be in areas where protection may be assumed, have clearly established international responsibility, and receive the concerned parties' agreement to the concept and location.",
      "spans": [
        "src:50142ad6d920#p1.4"
      ]
    },
    {
      "id": "F8",
      "kind": "capability",
      "status": "confirmed",
      "fact": "The zones would require duly mandated international support for security and logistics, international organizations' assistance with installation and essential services, and capacity beyond the ICRC alone; the ICRC is ready to assist with establishment and operation.",
      "spans": [
        "src:50142ad6d920#p1.3",
        "src:50142ad6d920#p1.4"
      ]
    },
    {
      "id": "F9",
      "kind": "authority",
      "status": "confirmed",
      "fact": "The ICRC recommends that the international community establish protected zones, with northern Bosnia-Herzegovina as the priority and possible consideration of zones in central Bosnia-Herzegovina.",
      "spans": [
        "src:50142ad6d920#p1.3"
      ]
    }
  ],
  "options": {
    "O1": {
      "do": "The international community should approve establishing a protected zone in northern Bosnia-Herzegovina.",
      "move": "act",
      "disposition": "approve",
      "irreversible": false
    },
    "O2": {
      "do": "The international community should reject establishing a protected zone in northern Bosnia-Herzegovina.",
      "move": "act",
      "disposition": "reject",
      "irreversible": false
    }
  },
  "opposite_pair": [
    "O1",
    "O2"
  ],
  "real_option": "O1",
  "authored_options": [
    "O2"
  ],
  "no_opposite_reason": ""
}
